<?php
function countCamels($n, $t) {
    // dp[i][j][k][last] = number of ways to have i vertices, j humps, k valleys, ending with value last
    // last is in {1,2,3,4}
    // We need to track the direction to determine humps/valleys

    // Actually, let's think differently.
    // A hump at position j means y[j-1] < y[j] > y[j+1]
    // A valley at position j means y[j-1] > y[j] < y[j+1]

    // We can use DP where state is (position, current_y, previous_direction, humps_count, valleys_count)
    // But n is up to 20, t up to 10, y in 1..4
    // Let's use: dp[i][y][dir][h][v] where i is position (1-indexed), y is current y, dir is direction from previous to current (1 for up, -1 for down, 0 for start)
    // Actually, we need to know the previous y to determine if current position is a hump or valley when we add the next point.

    // Better approach: dp[i][y][h][v] where i is the current position, y is the current y-coordinate, h is number of humps so far, v is number of valleys so far.
    // But we also need to know the previous y to check if the previous position was a hump or valley.
    // So let's use: dp[i][prev_y][curr_y][h][v]
    // i from 1 to n, prev_y and curr_y from 1 to 4, h from 0 to t, v from 0 to t-1

    // Initialize: for i=1, there's no previous, so we just set dp[1][0][y][0][0] = 1 for y in 1..4
    // Actually, let's use i as the number of points placed. When we place point i, we have y_i.
    // When we place point i+1 with y_{i+1}, we can check if point i is a hump or valley.
    // Point i is a hump if y_{i-1} < y_i > y_{i+1}
    // Point i is a valley if y_{i-1} > y_i < y_{i+1}

    // So dp[i][y_{i-1}][y_i][h][v] = number of ways to have i points, with (i-1)-th point at y_{i-1}, i-th point at y_i, with h humps and v valleys among positions 2 to i-1.

    // Base case: i=1, no previous. Let's handle i=2 separately or use a dummy.
    // Let's say dp[1][0][y][0][0] = 1 for y in 1..4 (0 represents no previous)
    // Then for i=2, we go from dp[1][0][y1][0][0] to dp[2][y1][y2][0][0] where y1 != y2 (no horizontal segment)
    // For i >= 3, when adding y_i, we check if position i-1 is a hump or valley based on y_{i-2}, y_{i-1}, y_i.

    $maxY = 4;
    $maxH = $t;
    $maxV = $t - 1;

    // dp[i][prev][curr][h][v]
    // Use a 5D array or nested arrays
    // Since n <= 20, maxY=4, maxH<=10, maxV<=9, this is manageable

    // Initialize dp for i=1
    $dp = array();
    for ($y = 1; $y <= $maxY; $y++) {
        $dp[1][0][$y][0][0] = 1;
    }

    for ($i = 2; $i <= $n; $i++) {
        for ($prev = 0; $prev <= $maxY; $prev++) {
            for ($curr = 1; $curr <= $maxY; $curr++) {
                for ($h = 0; $h <= $maxH; $h++) {
                    for ($v = 0; $v <= $maxV; $v++) {
                        if (!isset($dp[$i-1][$prev][$curr][$h][$v])) continue;
                        $count = $dp[$i-1][$prev][$curr][$h][$v];
                        if ($count == 0) continue;

                        for ($next = 1; $next <= $maxY; $next++) {
                            if ($next == $curr) continue; // no horizontal segment

                            $newH = $h;
                            $newV = $v;

                            if ($i >= 3) {
                                // Check if position i-1 is a hump or valley
                                // Position i-1 has y_{i-2}=$prev, y_{i-1}=$curr, y_i=$next
                                if ($prev < $curr && $curr > $next) {
                                    $newH = $h + 1;
                                } elseif ($prev > $curr && $curr < $next) {
                                    $newV = $v + 1;
                                }
                            }

                            if ($newH > $maxH || $newV > $maxV) continue;

                            if (!isset($dp[$i][$curr][$next][$newH][$newV])) {
                                $dp[$i][$curr][$next][$newH][$newV] = 0;
                            }
                            $dp[$i][$curr][$next][$newH][$newV] += $count;
                        }
                    }
                }
            }
        }
    }

    $result = 0;
    for ($prev = 1; $prev <= $maxY; $prev++) {
        for ($curr = 1; $curr <= $maxY; $curr++) {
            if (isset($dp[$n][$prev][$curr][$t][$t-1])) {
                $result += $dp[$n][$prev][$curr][$t][$t-1];
            }
        }
    }

    return $result;
}

$input = trim(fgets(STDIN));
$parts = explode(' ', $input);
$n = (int)$parts[0];
$t = (int)$parts[1];

echo countCamels($n, $t) . "\n";
?>
