<?php
$n = 0;
$t = 0;
if (fscanf(STDIN, "%d %d", $n, $t) !== 2) {
    exit(0);
}

// dp[i][j][k][l] where:
// i = number of vertices processed (from 1 to n)
// j = number of humps (peaks) so far
// k = number of valleys (troughs) so far
// l = last y value (1..4)
// We need to track the direction of the last segment to determine if a new peak/valley is formed.
// Actually, we can track the last two y values, or the last y and the direction.
// Let's use: dp[i][last_y][humps][valleys][last_direction]
// last_direction: 0 = up (y increased), 1 = down (y decreased)
// But at i=1, there's no direction. At i=2, we have a direction.
// Let's define state as: dp[i][y][humps][valleys][dir]
// where dir is 0 if last step was up, 1 if last step was down.
// For i=1, we can initialize separately.

// Max n=20, max y=4, max humps=10, max valleys=10
// Dimensions: [21][5][11][11][2]

$dp = array();
for ($i = 0; $i <= $n; $i++) {
    for ($y = 0; $y <= 4; $y++) {
        for ($h = 0; $h <= $t; $h++) {
            for ($v = 0; $v <= $t; $v++) {
                for ($d = 0; $d <= 1; $d++) {
                    $dp[$i][$y][$h][$v][$d] = 0;
                }
            }
        }
    }
}

// Initialize for i=1: y can be 1..4, humps=0, valleys=0, dir doesn't matter (set both to 1? or handle separately)
// Actually, for i=1, we haven't made a move yet. Let's start from i=2.
// For i=1, we place the first point. Then for i=2, we choose y2 != y1, and set dir.

// Let's initialize i=1 states. We'll use a separate array or just handle i=1 specially.
// Better: initialize dp[1][y][0][0][0] and dp[1][y][0][0][1] both to 1? No, that would double count.
// Instead, let's start from i=2.

// For i=1: for each y in 1..4, we have 1 way. But we need to track the "previous" state.
// Let's redefine: dp[i][y][humps][valleys][dir] represents the number of ways to have i vertices,
// ending at y, with humps peaks, valleys troughs, and the last segment (from i-1 to i) having direction dir.
// For i=1, there is no last segment. So we handle i=1 as a base case and start transitions from i=2.

// Base: i=1
for ($y = 1; $y <= 4; $y++) {
    // We'll store this in a way that allows transition to i=2.
    // Let's use a separate array for i=1, or just set dp[1][y][0][0][0] = 1 and dp[1][y][0][0][1] = 1? No.
    // Let's just use a 2D array for the first step.
}

// Alternative approach: use dp[i][y][humps][valleys][prev_dir] where prev_dir is the direction of the segment ending at i.
// For i=1, there is no prev_dir. So let's start from i=2.

// Let's create a new dp array for i >= 2.
// dp2[i][y][humps][valleys][dir]
// For i=2: for each y1 in 1..4, for each y2 in 1..4, y2 != y1:
//   dir = (y2 > y1) ? 0 : 1
//   humps = 0, valleys = 0
//   dp2[2][y2][0][0][dir] += 1

$dp2 = array();
for ($i = 0; $i <= $n; $i++) {
    for ($y = 0; $y <= 4; $y++) {
        for ($h = 0; $h <= $t; $h++) {
            for ($v = 0; $v <= $t; $v++) {
                for ($d = 0; $d <= 1; $d++) {
                    $dp2[$i][$y][$h][$v][$d] = 0;
                }
            }
        }
    }
}

// Initialize i=2
for ($y1 = 1; $y1 <= 4; $y1++) {
    for ($y2 = 1; $y2 <= 4; $y2++) {
        if ($y1 == $y2) continue;
        $dir = ($y2 > $y1) ? 0 : 1; // 0=up, 1=down
        $dp2[2][$y2][0][0][$dir] += 1;
    }
}

// Transition from i to i+1 for i from 2 to n-1
for ($i = 2; $i < $n; $i++) {
    for ($y = 1; $y <= 4; $y++) {
        for ($h = 0; $h <= $t; $h++) {
            for ($v = 0; $v <= $t; $v++) {
                for ($d = 0; $d <= 1; $d++) {
                    $count = $dp2[$i][$y][$h][$v][$d];
                    if ($count == 0) continue;
                    for ($ny = 1; $ny <= 4; $ny++) {
                        if ($ny == $y) continue; // no horizontal segment
                        $new_dir = ($ny > $y) ? 0 : 1;
                        $new_h = $h;
                        $new_v = $v;
                        // Check if a peak or valley is formed at position i
                        // A peak at i means: previous segment was up (d=0) and current segment is down (new_dir=1)
                        // A valley at i means: previous segment was down (d=1) and current segment is up (new_dir=0)
                        if ($d == 0 && $new_dir == 1) {
                            // peak at i
                            $new_h = $h + 1;
                        } elseif ($d == 1 && $new_dir == 0) {
                            // valley at i
                            $new_v = $v + 1;
                        }
                        // If new_h > t or new_v > t, skip (but we can still compute, just won't be used in final answer)
                        if ($new_h <= $t && $new_v <= $t) {
                            $dp2[$i+1][$ny][$new_h][$new_v][$new_dir] += $count;
                        }
                    }
                }
            }
        }
    }
}

// After processing up to i=n, we need to check the conditions.
// The conditions are:
// - exactly t humps (peaks)
// - exactly t-1 valleys (troughs)
// Note: The peaks and valleys are counted at internal vertices (2 <= j <= n-1).
// In our DP, when we transition from i to i+1, we check if vertex i is a peak or valley.
// So for vertex n, we never check it as a peak/valley because there's no next segment.
// This is correct: peaks/valleys are only at j where 2 <= j <= n-1.

// So the answer is the sum of dp2[n][y][t][t-1][d] for all y in 1..4 and d in 0..1.
$answer = 0;
for ($y = 1; $y <= 4; $y++) {
    for ($d = 0; $d <= 1; $d++) {
        $answer += $dp2[$n][$y][$t][$t-1][$d];
    }
}

echo $answer . "\n";
?>
