<?php
readline();
function readline() {
    $line = fgets(STDIN);
    if ($line === false) return null;
    $line = trim($line);
    if ($line === '') return null;
    return $line;
}

// Read input
$line = readline();
if ($line === null) {
    return;
}
$parts = explode(' ', $line);
$n = (int)$parts[0];
$t = (int)$parts[1];

// We need to count sequences y1, y2, ..., yn where:
// - each yi is in {1, 2, 3, 4}
// - no two consecutive yi are equal (no segment parallel to Ox-axis)
// - number of local maxima (peaks) = t: indices j (2<=j<=n-1) with y[j-1] < y[j] > y[j+1]
// - number of local minima (valleys) = t-1: indices j (2<=j<=n-1) with y[j-1] > y[j] < y[j+1]

// We can use DP.
// State: position i (1-indexed), current value y[i], previous value y[i-1], 
//        number of peaks so far, number of valleys so far.
// But we need to be careful: peaks and valleys are determined at position j when we have y[j-1], y[j], y[j+1].
// So when we are at position i, and we've chosen y[1..i], we can determine whether position i-1 is a peak or valley 
// once we know y[i-2], y[i-1], y[i].

// Let's define dp[i][prev][curr][peaks][valleys] = number of ways to have a sequence of length i,
// ending with y[i-1]=prev, y[i]=curr, with 'peaks' peaks and 'valleys' valleys among positions 2..i-1.
// Wait, peaks and valleys are counted at positions j where 2<=j<=n-1. When we add a new element at position i,
// we can determine if position i-1 is a peak or valley (since we now have y[i-2], y[i-1], y[i]).

// Actually, let's redefine:
// dp[i][a][b][p][v] = number of sequences of length i, where y[i-1]=a, y[i]=b,
// and among positions 2..i-1, there are p peaks and v valleys.
// Base case: i=2, dp[2][a][b][0][0] = 1 for all a != b, a,b in {1,2,3,4}.
// Transition: from state (i, a, b, p, v) to (i+1, b, c, p', v') where c in {1,2,3,4}, c != b.
// When we add c at position i+1, we can check if position i (which has value b, with previous a and next c) is a peak or valley.
// If a < b > c, then position i is a peak: p' = p+1, v' = v.
// If a > b < c, then position i is a valley: p' = p, v' = v+1.
// Otherwise: p' = p, v' = v.

// At the end, we want dp[n][a][b][t][t-1] for all a, b.

// Constraints: n <= 20, t <= 10, values 1-4.
// So p can be at most t (10), v can be at most t-1 (9).
// We can use a 5D array or nested loops.

// Let's use a 5D array: dp[i][a][b][p][v]
// i from 2 to n
// a, b from 1 to 4
// p from 0 to t
// v from 0 to t-1

$dp = array();

// Initialize for i=2
for ($a = 1; $a <= 4; $a++) {
    for ($b = 1; $b <= 4; $b++) {
        if ($a == $b) continue;
        $dp[2][$a][$b][0][0] = 1;
    }
}

// Fill for i from 3 to n
for ($i = 3; $i <= $n; $i++) {
    for ($a = 1; $a <= 4; $a++) {
        for ($b = 1; $b <= 4; $b++) {
            if ($a == $b) continue;
            for ($p = 0; $p <= $t; $p++) {
                for ($v = 0; $v <= $t - 1; $v++) {
                    if (!isset($dp[$i - 1][$a][$b][$p][$v])) continue;
                    $count = $dp[$i - 1][$a][$b][$p][$v];
                    for ($c = 1; $c <= 4; $c++) {
                        if ($c == $b) continue;
                        $np = $p;
                        $nv = $v;
                        // Check if position i-1 (value b, prev a, next c) is peak or valley
                        if ($a < $b && $b > $c) {
                            $np = $p + 1;
                        } elseif ($a > $b && $b < $c) {
                            $nv = $v + 1;
                        }
                        if ($np <= $t && $nv <= $t - 1) {
                            if (!isset($dp[$i][$b][$c][$np][$nv])) {
                                $dp[$i][$b][$c][$np][$nv] = 0;
                            }
                            $dp[$i][$b][$c][$np][$nv] += $count;
                        }
                    }
                }
            }
        }
    }
}

// Sum up all dp[n][a][b][t][t-1] for all a, b
$result = 0;
for ($a = 1; $a <= 4; $a++) {
    for ($b = 1; $b <= 4; $b++) {
        if ($a == $b) continue;
        if (isset($dp[$n][$a][$b][$t][$t - 1])) {
            $result += $dp[$n][$a][$b][$t][$t - 1];
        }
    }
}

echo $result;
?>
